const incoming = $input.first().json;
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;

const consultationId = Number(body.consultation_id);
const topic = typeof body.topic === 'string' ? body.topic.trim() : '';
const context = body.context == null ? '' : String(body.context).trim();
const sharing = body.sharing && typeof body.sharing === 'object' ? body.sharing : {};
const materials = body.materials && typeof body.materials === 'object' ? body.materials : {};

if (!Number.isInteger(consultationId) || consultationId < 1) {
  throw new Error('VALIDATION_ERROR: consultation_id harus berupa bilangan bulat positif.');
}
if (!topic || topic.length > 120) {
  throw new Error('VALIDATION_ERROR: topic wajib diisi dan maksimal 120 karakter.');
}
if (context.length > 10000) {
  throw new Error('VALIDATION_ERROR: context melebihi 10.000 karakter.');
}
if (typeof sharing.share_journal !== 'boolean' || typeof sharing.share_ai_reflection !== 'boolean') {
  throw new Error('VALIDATION_ERROR: status persetujuan sharing harus berupa boolean.');
}

const journal = materials.journal ?? null;
const reflection = materials.ai_reflection ?? null;

if (sharing.share_journal) {
  if (!journal || typeof journal !== 'object' || typeof journal.content !== 'string' || !journal.content.trim()) {
    throw new Error('VALIDATION_ERROR: snapshot jurnal yang disetujui tidak tersedia.');
  }
  if (journal.content.length > 20000) {
    throw new Error('VALIDATION_ERROR: snapshot jurnal melebihi batas 20.000 karakter.');
  }
} else if (journal !== null) {
  throw new Error('VALIDATION_ERROR: materi jurnal dikirim tanpa persetujuan.');
}

if (sharing.share_ai_reflection) {
  if (!reflection || typeof reflection !== 'object' || typeof reflection.summary !== 'string' || !reflection.summary.trim()) {
    throw new Error('VALIDATION_ERROR: snapshot AI Reflection yang disetujui tidak tersedia.');
  }
} else if (reflection !== null) {
  throw new Error('VALIDATION_ERROR: AI Reflection dikirim tanpa persetujuan.');
}

return [{
  json: {
    consultation_id: consultationId,
    submitted_at: typeof body.submitted_at === 'string' ? body.submitted_at : null,
    topic,
    context,
    sharing: {
      share_journal: sharing.share_journal,
      share_ai_reflection: sharing.share_ai_reflection,
      consent_at: sharing.consent_at ?? null
    },
    materials: {
      journal: sharing.share_journal ? journal : null,
      ai_reflection: sharing.share_ai_reflection ? reflection : null
    }
  }
}];

const response = $input.first().json;
const raw = response?.choices?.[0]?.message?.content;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('HERMES_RESPONSE_ERROR: respons Hermes tidak berisi teks.');
}

let parsed;
try {
  const cleaned = raw.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('HERMES_RESPONSE_ERROR: output Hermes bukan JSON valid.');
}

const brief = typeof parsed.consultation_brief === 'string'
  ? parsed.consultation_brief.trim()
  : '';

if (!brief || brief.length < 20 || brief.length > 12000) {
  throw new Error('HERMES_RESPONSE_ERROR: consultation_brief kosong atau di luar batas panjang.');
}

const request = $('Prepare Hermes Context').first().json;
return [{
  json: {
    success: true,
    consultation_id: request.consultation_id,
    consultation_brief: brief,
    generated_at: new Date().toISOString(),
    ai_model: response.model || 'temandengar'
  }
}];
